//go:build loong64

package floats

import "golang.org/x/sys/cpu"

// LASX kernels (256-bit; not on every LoongArch CPU, so gated on hasLASX): the
// float64 Add, Sub, Mul, Div, Sqrt of go-ndarray and the pairwise-sum block,
// generated by go-asmgen (lanes_loong64_gen.go) into lanes_loong64.s. One IEEE
// operation per element, no fused instruction: bit-identical to the scalar loops.
// The callers pass every slice already sliced to the common length.
//
//go:noescape
func addLASX(dst, a, b *float64, n int)

//go:noescape
func subLASX(dst, a, b *float64, n int)

//go:noescape
func mulLASX(dst, a, b *float64, n int)

//go:noescape
func divLASX(dst, a, b *float64, n int)

//go:noescape
func sqrtLASX(dst, src *float64, n int)

// pwBlockLASX is the 8 <= n <= 128 block of DOUBLE_pairwise_sum.
//
//go:noescape
func pwBlockLASX(a *float64, n int) float64

// hasLASX gates the kernels above; a var so a test can drive the fallback.
var hasLASX = cpu.Loong64.HasLASX

func add(dst, a, b []float64) {
	if len(a) == 0 || !hasLASX {
		addRef(dst, a, b)
		return
	}
	addLASX(&dst[0], &a[0], &b[0], len(a))
}

func sub(dst, a, b []float64) {
	if len(a) == 0 || !hasLASX {
		subRef(dst, a, b)
		return
	}
	subLASX(&dst[0], &a[0], &b[0], len(a))
}

func mul(dst, a, b []float64) {
	if len(a) == 0 || !hasLASX {
		mulRef(dst, a, b)
		return
	}
	mulLASX(&dst[0], &a[0], &b[0], len(a))
}

func div(dst, a, b []float64) {
	if len(a) == 0 || !hasLASX {
		divRef(dst, a, b)
		return
	}
	divLASX(&dst[0], &a[0], &b[0], len(a))
}

func sqrt(dst, src []float64) {
	if len(src) == 0 || !hasLASX {
		sqrtRef(dst, src)
		return
	}
	sqrtLASX(&dst[0], &src[0], len(src))
}

func clampScalar(dst, v []float64, lo, hi float64) { clampScalarRef(dst, v, lo, hi) }

func pairwiseBlock(a []float64) float64 {
	if !hasLASX {
		return pairwiseBlockRef(a)
	}
	return pwBlockLASX(&a[0], len(a))
}
